-- Cards with no pit or TBA robot photo show the team's FIRST logo. The app fetched it from TBA
-- after each card appeared, which was slow; now the logo is stored with the card (a data URL)
-- and image_kind says to draw it as a logo, so it arrives with the card itself.
ALTER TABLE tcg_cards ADD COLUMN IF NOT EXISTS image_kind TEXT NOT NULL DEFAULT 'photo'
  CHECK (image_kind IN ('photo', 'logo'));

UPDATE tcg_cards SET image_url = 'data:image/png;base64,', image_kind = 'logo'
  WHERE team_number = 8768 AND image_url IS NULL;
UPDATE tcg_cards SET image_url = 'data:image/png;base64,', image_kind = 'logo'
  WHERE team_number = 9584 AND image_url IS NULL;
